    /**
     * Creates new form JFontChooser
     */
    public JFontChooser() {
        org.jhotdraw.gui.JFontChooser.loadAllFonts();
        model = new org.jhotdraw.gui.fontchooser.DefaultFontChooserModel.UIResource();
        model.addTreeModelListener(modelHandler);
        updateUI();
        addPropertyChangeListener(new java.beans.PropertyChangeListener() {
            @java.lang.Override
            public void propertyChange(java.beans.PropertyChangeEvent evt) {
                if ("ancestor".equals(evt.getPropertyName()) && (evt.getNewValue() != null)) {
                    try {
                        ((org.jhotdraw.gui.fontchooser.DefaultFontChooserModel) (model)).setFonts(org.jhotdraw.gui.JFontChooser.getAllFonts());
                    } catch (java.lang.Exception ex) {
                        ex.printStackTrace();
                    }
                    JFontChooser.this.removePropertyChangeListener(this);
                }
            }
        });
    }

    /**
     * Resets the UI property with a value from the current look and feel.
     *
     * @see JComponent#updateUI
     */
    @java.lang.Override
    public void updateUI() {
        // Try to get a browser UI from the UIManager.
        // Fall back to BasicBrowserUI, if none is available.
        if (javax.swing.UIManager.get(getUIClassID()) != null) {
            setUI(((org.jhotdraw.gui.plaf.FontChooserUI) (javax.swing.UIManager.getUI(this))));
        } else {
            setUI(org.jhotdraw.gui.plaf.palette.PaletteFontChooserUI.createUI(this));
        }
    }

