    /**
     * Called by the UI when the user hits the Approve button (labeled "Open" or "Save", by default).
     * This can also be called by the programmer. This method causes an action event to fire with the
     * command string equal to <code>APPROVE_SELECTION</code>.
     *
     * @see #APPROVE_SELECTION
     */
    public void approveSelection() {
        returnValue = org.jhotdraw.gui.JFontChooser.APPROVE_OPTION;
        if (dialog != null) {
            dialog.setVisible(false);
        }
        fireActionPerformed(org.jhotdraw.gui.JFontChooser.APPROVE_SELECTION);
    }

    /**
     * Called by the UI when the user chooses the Cancel button. This can also be called by the
     * programmer. This method causes an action event to fire with the command string equal to <code>
     * CANCEL_SELECTION</code>.
     *
     * @see #CANCEL_SELECTION
     */
    public void cancelSelection() {
        returnValue = org.jhotdraw.gui.JFontChooser.CANCEL_OPTION;
        if (dialog != null) {
            dialog.setVisible(false);
        }
        fireActionPerformed(org.jhotdraw.gui.JFontChooser.CANCEL_SELECTION);
    }

