    /**
     * Notifies all listeners that have registered interest for notification on this event type. The
     * event instance is lazily created using the <code>command</code> parameter.
     */
    protected void fireActionPerformed(java.lang.String command) {
        // Guaranteed to return a non-null array
        java.lang.Object[] listeners = listenerList.getListenerList();
        long mostRecentEventTime = java.awt.EventQueue.getMostRecentEventTime();
        int modifiers = 0;
        java.awt.AWTEvent currentEvent = java.awt.EventQueue.getCurrentEvent();
        if (currentEvent instanceof java.awt.event.InputEvent) {
            modifiers = ((java.awt.event.InputEvent) (currentEvent)).getModifiers();
        } else if (currentEvent instanceof java.awt.event.ActionEvent) {
            modifiers = ((java.awt.event.ActionEvent) (currentEvent)).getModifiers();
        }
        java.awt.event.ActionEvent e = null;
        // Process the listeners last to first, notifying
        // those that are interested in this event
        for (int i = listeners.length - 2; i >= 0; i -= 2) {
            if (listeners[i] == java.awt.event.ActionListener.class) {
                // Lazily create the event:
                if (e == null) {
                    e = new java.awt.event.ActionEvent(this, java.awt.event.ActionEvent.ACTION_PERFORMED, command, mostRecentEventTime, modifiers);
                }
                ((java.awt.event.ActionListener) (listeners[i + 1])).actionPerformed(e);
            }
        }
    }

