    /**
     * Sets the selected Font. This is a bound property.
     *
     * <p>Changing the selection path, causes a change of the selected font, if the selected font is
     * not the last path segment of the selection path.
     *
     * @param newValue
     * 		The new selected font, or null if no font is to be selected..
     */
    public void setSelectionPath(javax.swing.tree.TreePath newValue) {
        javax.swing.tree.TreePath oldValue = selectionPath;
        this.selectionPath = newValue;
        firePropertyChange(org.jhotdraw.gui.JFontChooser.SELECTION_PATH_PROPERTY, oldValue, newValue);
        if ((selectionPath != null) && (selectionPath.getPathCount() == 4)) {
            setSelectedFont(((org.jhotdraw.gui.fontchooser.FontFaceNode) (selectionPath.getLastPathComponent())).getFont());
        }
    }

    /**
     * Starts loading all fonts from the local graphics environment using a worker thread.
     */
    public static synchronized void loadAllFonts() {
        if (org.jhotdraw.gui.JFontChooser.future == null) {
            org.jhotdraw.gui.JFontChooser.future = new java.util.concurrent.FutureTask<>(new java.util.concurrent.Callable<java.awt.Font[]>() {
                @java.lang.Override
                public java.awt.Font[] call() throws java.lang.Exception {
                    java.awt.Font[] fonts = java.awt.GraphicsEnvironment.getLocalGraphicsEnvironment().getAllFonts();
                    // get rid of bogus fonts
                    java.util.ArrayList<java.awt.Font> goodFonts = new java.util.ArrayList<>(fonts.length);
                    for (java.awt.Font f : fonts) {
                        // System.out.println("JFontChooser "+f.getFontName());
                        java.awt.Font decoded = java.awt.Font.decode(f.getFontName());
                        if (decoded.getFontName().equals(f.getFontName()) || decoded.getFontName().endsWith("-Derived")) {
                            goodFonts.add(f);
                        } else {
                            // System.out.println("JFontChooser ***bogus*** "+decoded.getFontName());
                        }
                    }
                    return goodFonts.toArray(new java.awt.Font[goodFonts.size()]);
                    // return fonts;
                }
            });
            new java.lang.Thread(org.jhotdraw.gui.JFontChooser.future).start();
        }
    }

    /**
     * Gets all fonts from the graphics environment. This may take a long time. It is recommended to
     * call loadAllFonts during the startup of an application. If you do this, you can retrieve the
     * fonts from this method from the AWT Event Dispatcher Thread.
     *
     * @return All fonts.
     */
    public static synchronized java.awt.Font[] getAllFonts() {
        org.jhotdraw.gui.JFontChooser.loadAllFonts();
        try {
            return org.jhotdraw.gui.JFontChooser.future.get().clone();
        } catch (java.lang.InterruptedException | java.util.concurrent.ExecutionException ex) {
            return new java.awt.Font[0];
        }
    }

