    /**
     * Sets the selected Font.
     *
     * <p>Changing the selected font, causes a change of the selection path, if the selected font is
     * not the last path segment of the selection path.
     *
     * <p>This is a bound property.
     *
     * @param newValue
     * 		The new selected font, or null if no font is to be selected.
     */
    public void setSelectedFont(java.awt.Font newValue) {
        java.awt.Font oldValue = selectedFont;
        this.selectedFont = newValue;
        firePropertyChange(org.jhotdraw.gui.JFontChooser.SELECTED_FONT_PROPERTY, oldValue, newValue);
        updateSelectionPath(newValue);
    }

    /**
     * Updates the selection path to the selected font.
     *
     * <p>This method is invoked, when a font is selected, and when then structure of the model has
     * changed.
     *
     * @param newValue
     */
    protected void updateSelectionPath(java.awt.Font newValue) {
        if ((((newValue == null) || (selectionPath == null)) || (selectionPath.getPathCount() != 4)) || (!((org.jhotdraw.gui.fontchooser.FontFaceNode) (selectionPath.getLastPathComponent())).getFont().getFontName().equals(newValue.getFontName()))) {
            if (newValue == null) {
                setSelectionPath(null);
            } else {
                javax.swing.tree.TreePath path = selectionPath;
                org.jhotdraw.gui.fontchooser.FontCollectionNode oldCollection = ((path != null) && (path.getPathCount() > 1)) ? ((org.jhotdraw.gui.fontchooser.FontCollectionNode) (path.getPathComponent(1))) : null;
                org.jhotdraw.gui.fontchooser.FontFamilyNode oldFamily = ((path != null) && (path.getPathCount() > 2)) ? ((org.jhotdraw.gui.fontchooser.FontFamilyNode) (path.getPathComponent(2))) : null;
                org.jhotdraw.gui.fontchooser.FontFaceNode oldFace = ((path != null) && (path.getPathCount() > 3)) ? ((org.jhotdraw.gui.fontchooser.FontFaceNode) (path.getPathComponent(3))) : null;
                org.jhotdraw.gui.fontchooser.FontCollectionNode newCollection = oldCollection;
                org.jhotdraw.gui.fontchooser.FontFamilyNode newFamily = oldFamily;
                org.jhotdraw.gui.fontchooser.FontFaceNode newFace = null;
                // search in the current family
                if ((newFace == null) && (newFamily != null)) {
                    for (org.jhotdraw.gui.fontchooser.FontFaceNode face : newFamily.faces()) {
                        if (face.getFont().getFontName().equals(newValue.getFontName())) {
                            newFace = face;
                            break;
                        }
                    }
                }
                // search in the current collection
                if ((newFace == null) && (newCollection != null)) {
                    for (org.jhotdraw.gui.fontchooser.FontFamilyNode family : newCollection.families()) {
                        for (org.jhotdraw.gui.fontchooser.FontFaceNode face : family.faces()) {
                            if (face.getFont().getFontName().equals(newValue.getFontName())) {
                                newFamily = family;
                                newFace = face;
                                break;
                            }
                        }
                    }
                }
                // search in all collections
                if (newFace == null) {
                    javax.swing.tree.TreeNode root = ((javax.swing.tree.TreeNode) (getModel().getRoot()));
                    OuterLoop : for (int i = 0, n = root.getChildCount(); i < n; i++) {
                        org.jhotdraw.gui.fontchooser.FontCollectionNode collection = ((org.jhotdraw.gui.fontchooser.FontCollectionNode) (root.getChildAt(i)));
                        for (org.jhotdraw.gui.fontchooser.FontFamilyNode family : collection.families()) {
                            for (org.jhotdraw.gui.fontchooser.FontFaceNode face : family.faces()) {
                                if (face.getFont().getFontName().equals(newValue.getFontName())) {
                                    newCollection = collection;
                                    newFamily = family;
                                    newFace = face;
                                    break OuterLoop;
                                }
                            }
                        }
                    }
                }
                if (newFace != null) {
                    setSelectionPath(new javax.swing.tree.TreePath(new java.lang.Object[]{ getModel().getRoot(), newCollection, newFamily, newFace }));
                } else {
                    setSelectionPath(null);
                }
            }
        }
    }

    /**
     * Gets the selected Font. This is a bound property.
     *
     * @return The selected font, or null, if no font is selected.
     */
    public org.jhotdraw.gui.fontchooser.FontChooserModel getModel() {
        return model;
    }

    /**
     * Sets the selected Font. This is a bound property.
     *
     * @param newValue
     * 		The new selected font, or null if no font is to be selected..
     */
    public void setModel(org.jhotdraw.gui.fontchooser.FontChooserModel newValue) {
        org.jhotdraw.gui.fontchooser.FontChooserModel oldValue = model;
        if (oldValue != null) {
            oldValue.removeTreeModelListener(modelHandler);
        }
        this.model = newValue;
        if (newValue != null) {
            newValue.addTreeModelListener(modelHandler);
        }
        firePropertyChange(org.jhotdraw.gui.JFontChooser.MODEL_PROPERTY, oldValue, newValue);
        updateSelectionPath(selectedFont);
    }
